args.query:
let DownloadWindow = 5m;
let StagingDirs = dynamic(["/tmp/", "/var/tmp/", "/dev/shm/"]);
deviceProcessDownloads
    | join kind=inner deviceProcessShellExecs on DeviceId, $left.DownloaderPid == $right.ExecParentPid,
        (
            abs_datetime(TimestampExecute - TimestampDownload) <= bin_duration(5m)
        )
| extend ExecutedFile = tolower(tostring(extract(@"^\S*(?:bash|sh|dash|zsh)\s+(?:-[\w]+\s+)*([^\s'\|&]+)", 1, CommandLineExecute)))
| mv-if package version
